// Extraire le job_id des query params
const input = $input.first().json;
const query = input.query || {};

const jobId = query.job_id || null;

if (!jobId) {
  return [{
    json: {
      success: false,
      error: {
        code: 400,
        message: 'Le paramètre "job_id" est requis',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Chemin du fichier job
const jobPath = `/tmp/torah-jobs/${jobId}.json`;

return [{
  json: {
    valid: true,
    jobId: jobId,
    jobPath: jobPath
  }
}];

// Lire le fichier job
const input = $input.first().json;
const fs = require('fs');

const jobPath = input.jobPath;
const jobId = input.jobId;

// Vérifier si le fichier existe
if (!fs.existsSync(jobPath)) {
  return [{
    json: {
      success: false,
      error: {
        code: 404,
        message: `Job non trouvé: ${jobId}`,
        status: 'JOB_NOT_FOUND'
      }
    }
  }];
}

// Lire et parser le fichier
let jobData;
try {
  const content = fs.readFileSync(jobPath, 'utf8');
  jobData = JSON.parse(content);
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Erreur lecture fichier job: ' + e.message,
        status: 'JOB_READ_ERROR'
      }
    }
  }];
}

// Calculer la progression
const current = jobData.current_segment || 0;
const total = jobData.segments_count || 0;
const percentage = total > 0 ? Math.round((current / total) * 100) : 0;

// Construire la réponse selon le statut
const response = {
  job_id: jobData.job_id,
  status: jobData.status,
  traite: jobData.traite,
  page: jobData.page,
  progress: {
    current: current,
    total: total,
    percentage: percentage
  },
  started_at: jobData.started_at
};

// Ajouter les infos selon le statut
if (jobData.status === 'in_progress') {
  // Ajouter le segment en cours si disponible
  if (jobData.segments && jobData.segments[current]) {
    const currentSegmentText = jobData.segments[current];
    response.current_segment = currentSegmentText.substring(0, 100) + (currentSegmentText.length > 100 ? '...' : '');
  }
}

if (jobData.status === 'completed') {
  response.completed_at = jobData.completed_at;
  // Calculer la durée
  if (jobData.started_at && jobData.completed_at) {
    const start = new Date(jobData.started_at);
    const end = new Date(jobData.completed_at);
    response.duration_seconds = Math.round((end - start) / 1000);
  }
  response.translations_saved = jobData.translations?.length || current;
}

if (jobData.status === 'failed') {
  response.error = jobData.error;
}

return [{ json: response }];
